(7644753, 1242325, 141542, '<td valign="top">A new angle, avoided cars, and a far less generous crop would make this a more interesting shot to me.</td>', 'A new angle, avoided cars, and a far less generous crop would make this a more interesting shot to me.', '2019-10-27 21:22:02.000000', NULL, 1),
(7644755, 1242101, 141542, '<td valign="top">There''s a lot of detail to absorb here, and the composition makes it difficult for me to choose where to start.</td>', 'There''s a lot of detail to absorb here, and the composition makes it difficult for me to choose where to start.', '2019-10-27 21:22:33.000000', NULL, 1),
